// Builds a Langfuse ingestion batch for the Extractor run.
// One trace (the run) + one generation (the Extractor agent).
// Slice 1 has a single agent; R2/R4 add one generation per agent.

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

function firstJson(name) {
  try {
    const items = $(name).all();
    if (items && items.length) return items[0].json;
  } catch (e) {}
  return null;
}
const src = firstJson('T1 Input') || firstJson('Transcript1 Input');
if (!src || !src.chatInput) {
  throw new Error('No selected input. Set testId to T1 or Transcript1 and run the full workflow.');
}
const out = $input.first().json;

// chainLlm returns { text }. Fall back rather than silently sending "[object Object]".
const outputText =
  typeof out.text === 'string' ? out.text :
  typeof out.output === 'string' ? out.output :
  JSON.stringify(out);

const traceId = uuid();
const startTime = src.startTime || new Date().toISOString();
const endTime = new Date().toISOString();
const testId = src.testId || 'unspecified';

const batch = [
  {
    id: uuid(),
    type: 'trace-create',
    timestamp: endTime,
    body: {
      id: traceId,
      name: 'prd-genie-slice1',
      input: src.chatInput,
      output: outputText,
      tags: ['prd-genie', 'slice1', testId],
      metadata: { testId, release: 'R1', platform: 'n8n-ik-cloud' },
    },
  },
  {
    id: uuid(),
    type: 'generation-create',
    timestamp: endTime,
    body: {
      id: uuid(),
      traceId,
      name: 'Requirement Extractor',
      model: 'gpt-4o',
      startTime,
      endTime,
      input: src.chatInput,
      output: outputText,
      metadata: { testId, agent: 'Requirement Extractor' },
    },
  },
];

// traceId is surfaced so it can be pasted into the Trace ID column of
// evidence/baseline-results.md. Never record a Pass without it.
return [{ json: { batch, traceId, testId, extractorOutput: outputText } }];
